/**
 * A one-shot reply capability: a token of the core's, or one minted on
 * another node and decoded here. `send` delivers exactly once — the guarantee
 * is the checker's; the runtime only enqueues.
 */
class SalvoReply internal constructor(private var token: salvo.runtime.RtToken?) {
    /** [addr-routable] For a token minted elsewhere: (node, kind, id, slot, bits). */
    internal var remote: LongArray? = null

    /** [wire-format] How a task's answer is decoded should it return over the wire. */
    internal var decode: (ByteArray) -> Pair<Boolean, Any?> = { _ -> Pair(false, null) }

    /** [platform-check] What a platform adapter checks of the value the host sends. */
    internal var check: ((Any?) -> Any?)? = null

    internal fun takeLocal(): salvo.runtime.RtToken? =
        synchronized(this) {
            val t = token
            token = null
            t
        }

    fun checked(f: (Any?) -> Any?): SalvoReply {
        check = f
        return this
    }

    fun send(value: Any?) {
        val f = check
        val v = if (f != null) f(value) else value
        val t = takeLocal() ?: error("internal: an untyped reply to a remote token")
        salvo.runtime.answer(t, Dyn(v))
    }

    /**
     * [platform-reply] Hands the token to host code that completes it later,
     * from any thread; until then the scheduler counts one outside source of
     * work, so a frame waiting on it is neither idle nor deadlocked. An unsent
     * host reply is not detected on this backend (the JVM has no drop).
     */
    fun hosted(): SalvoHostReply {
        salvo.runtime.externalBegin()
        return SalvoHostReply(this)
    }
}

/** [platform-reply] A reply the host has taken on: [send] completes it once, from any thread. */
class SalvoHostReply internal constructor(private val reply: SalvoReply) {
    private val sent = java.util.concurrent.atomic.AtomicBoolean(false)

    fun send(value: Any?) {
        check(sent.compareAndSet(false, true)) { "salvo: a host reply was sent twice [platform-reply]" }
        if (reply.remote != null) {
            error("salvo: a host-completed reply to a token minted on another node is not supported yet [platform-reply]")
        }
        reply.send(value)
        salvo.runtime.externalEnd()
    }
}

// [addr-routable] The codecs of the two scheduler handles live here, beside
// what they ask, so the wire stands alone in a program with no actors.
/** [addr-routable] An `Addr<E>` is a scheduler index; on the wire its routable identity, 24 bytes. */
object AddrCodec : WireCodec<Int> {
    override fun enc(v: Int, out: WireOut) {
        val r = SalvoSched.addrIdentity(v)
        out.i64(r.node); out.i64(r.actor); out.i64(r.bits)
    }
    override fun dec(inp: WireIn): Int = SalvoSched.importAddr(SalvoRemoteRef(inp.i64(), inp.i64(), inp.i64()))
}

/** [addr-routable] A `Reply<T>` on the wire: `(node, kind, id, slot, bits)`, 33 bytes. */
object ReplyCodec : WireCodec<SalvoReply> {
    override fun enc(v: SalvoReply, out: WireOut) {
        val e = SalvoSched.replyExport(v)
        out.i64(e[0]); out.u8(e[1].toInt()); out.i64(e[2]); out.i64(e[3]); out.i64(e[4])
    }
    override fun dec(inp: WireIn): SalvoReply {
        val node = inp.i64(); val kind = inp.u8(); val id = inp.i64(); val slot = inp.i64(); val bits = inp.i64()
        return SalvoSched.replyImport(node, kind, id, slot, bits)
    }
}
